      en: ["Part of Kuwait's 3rd City Wall", "Wall construction year: 1920", "Reason for construction: Defense against Ikhwan", "Material: Mudbrick and gypsum", "Orientation: West, towards Jahra", "Wall length: 6.4 km", "Wall demolition: 1957", "Status: Preserved and restored"],
      es: ["Parte de la 3.ª muralla de Kuwait", "Año de construcción de la muralla: 1920", "Motivo de construcción: Protección contra los Ikhwan", "Material: Ladrillos de barro y yeso", "Orientación: Oeste, hacia Jahra", "Longitud de la muralla: 6,4 km", "Demolición de la muralla: 1957", "Estado: Conservada y restaurada"],
      pt: ["Parte da 3ª muralha da cidade do Kuwait", "Ano de construção da muralha: 1920", "Razão da construção: Proteção contra os Ikhwan", "Material: Tijolos de barro e gesso", "Orientação: Oeste, em direção a Jahra", "Comprimento da muralha: 6,4 km", "Demolição da muralha: 1957", "Estado: Preservado e restaurado"],
      fr: ["Fait partie du 3ème mur d'enceinte du Koweït", "Année de construction du mur : 1920", "Raison de la construction : Protection contre les Ikhwan", "Matériau : Briques de boue et plâtre", "Orientation : Ouest, vers Jahra", "Longueur du mur : 6,4 km", "Démolition du mur : 1957", "Statut : Préservé et restauré"],
