    image: "/poi-images/naif-palace-history-v2.webp",
    description: {
      de: "Ein historischer Palastkomplex in Kuwait, der früher das Zentrum für Sicherheit und Polizei war.",
      hu: "Történelmi palotakomplexum Kuvaitban, amely korábban a biztonság és a rendőrség központja volt.",
      ro: "Un complex istoric de palate din Kuweit, care a fost centrul securității și al poliției.",
      en: "A historical palace complex in Kuwait that formerly served as the center for security and police.",
      es: "Un complejo palaciego histórico en Kuwait que anteriormente fue el centro de seguridad y policía.",
      pt: "Um complexo palaciano histórico no Kuwait que antigamente era o centro de segurança e polícia.",
      fr: "Un complexe palatial historique au Koweït, qui était autrefois le centre de la sécurité et de la police.",
    },
    facts: {
      de: [
        "Wurde 1919 aus Lehm erbaut.",
        "Der Hof war in der Vergangenheit ein Versammlungsort."
      ],
      hu: [
        "1919-ben épült vályogból.",
        "Az udvar a múltban fontos gyülekezőhely volt."
      ],
      ro: [
        "A fost construit din noroi în 1919.",
        "Curtea a fost un loc important de adunare în trecut."
      ],
      en: [
        "It was built of mud in 1919.",
        "The courtyard was an important gathering place in the past."
      ],
      es: ["Fue construido en barro en 1919.", "El patio fue un lugar de reunión en el pasado."],
      pt: ["Foi construído em barro em 1919.", "O pátio foi um local de reunião no passado."],
      fr: ["A été construit en boue en 1919.", "La cour était un lieu de rassemblement par le passé."],
    },
    descriptionAdvanced: {
      de: "Der Naif-Palast wurde 1919 unter der Herrschaft von Scheich Salem Al-Mubarak Al-Sabah erbaut. Ursprünglich als landwirtschaftliches Anwesen gedacht, wurde er schnell in das erste Hauptquartier für öffentliche Sicherheit des Landes umgewandelt. Der aus Lehmziegeln errichtete Palast ist ein hervorragendes Beispiel für die traditionelle Najdi-Architektur mit seinen hohen Mauern, kleinen Fenstern und einem großen zentralen Innenhof. Über Jahrzehnte hinweg war er das Zentrum der Polizei und des Innenministeriums. Besonders bekannt ist der Palast für die Ramadan-Kanonenschüsse, eine Tradition, bei der täglich ein Schuss abgefeuert wird, um das Fastenbrechen bei Sonnenuntergang zu signalisieren. Obwohl die Regierungsfunktionen inzwischen in moderne Gebäude verlegt wurden, bleibt der Naif-Palast ein wichtiges historisches Wahrzeichen und wird weiterhin für zeremonielle Zwecke genutzt, um die lange Geschichte der Rechtsstaatlichkeit in Kuwait zu ehren.",
      hu: "A Náif-palotát 1919-ben építtette Salem Al-Mubarak Al-Sabah sejk. Eredetileg mezőgazdasági birtoknak szánták, de hamarosan az ország első közbiztonsági főhadiszállásává alakították át. Az agyagtéglából épült palota a hagyományos nedzsdi építészet kiváló példája magas falaival, kis ablakaival és nagy központi udvarával. Évtizedeken át ez volt a rendőrség és a belügyminisztérium központja. A palota különösen a ramadáni ágyúlövésről ismert, egy hagyományról, amelynek során naponta lövést adnak le a napnyugtakor kezdődő böjt megtörésének jelzésére. Bár a kormányzati funkciókat mára modern épületekbe költöztették, a Náif-palota továbbra is fontos történelmi nevezetesség, és ceremoniális célokra használják, tisztelegve a kuvaiti jogállamiság hosszú története előtt.",
      ro: "Palatul Naif a fost construit în 1919 sub domnia șeicului Salem Al-Mubarak Al-Sabah. Inițial conceput ca o proprietate agricolă, a fost rapid transformat în primul sediu al securității publice din țară. Construit din cărămidă de noroi, palatul este un exemplu excelent de arhitectură tradițională Najdi, cu zidurile sale înalte, ferestrele mici și o curte centrală mare. Timp de decenii, a fost centrul poliției și al Ministerului de Interne. Palatul este deosebit de renumit pentru loviturile de tun de Ramadan, o tradiție în care se trage o salvă zilnic pentru a semnala ruperea postului la apus. Deși funcțiile guvernamentale s-au mutat de atunci în clădiri moderne, Palatul Naif rămâne un important punct de reper istoric și continuă să fie folosit în scopuri ceremoniale, onorând lunga istorie a statului de drept din Kuweit.",
      en: "Naif Palace was built in 1919 under the rule of Sheikh Salem Al-Mubarak Al-Sabah. Originally intended as an agricultural estate, it was quickly repurposed to become the country's first public security headquarters. Constructed from mudbrick, the palace is a prime example of traditional Najdi architecture, with its high walls, small windows, and a large central courtyard. For decades, it served as the center for the police and the Ministry of Interior. The palace is particularly famous for the Ramadan cannon firing, a tradition where a shot is fired daily to signal the breaking of the fast at sunset. Although government functions have since moved to modern buildings, Naif Palace remains an important historical landmark and continues to be used for ceremonial purposes, honoring Kuwait's long history of law and order.",
      es: "El Palacio Naif fue construido en 1919 bajo el reinado del Jeque Salem Al-Mubarak Al-Sabah. Concebido originalmente como una finca agrícola, se transformó rápidamente en el primer cuartel general de seguridad pública del país. Construido con ladrillos de barro, el palacio es un excelente ejemplo de la arquitectura tradicional Najdi, con sus muros altos, ventanas pequeñas y un gran patio central. Durante décadas fue el centro de la policía y del Ministerio del Interior. El palacio es especialmente conocido por los disparos de cañón del Ramadán, una tradición en la que se dispara un cañonazo diario para señalar la ruptura del ayuno al atardecer. Aunque las funciones gubernamentales se han trasladado a edificios modernos, el Palacio Naif sigue siendo un importante hito histórico y se sigue utilizando para fines ceremoniales para honrar la larga historia del estado de derecho en Kuwait.",
      pt: "O Palácio Naif foi construído em 1919 sob o reinado do Xeque Salem Al-Mubarak Al-Sabah. Originalmente concebido como uma propriedade agrícola, foi rapidamente transformado no primeiro quartel-general de segurança pública do país. Construído com tijolos de barro, o palácio é um excelente exemplo da arquitetura tradicional Najdi, com as suas muralhas altas, janelas pequenas e um grande pátio central. Durante décadas, foi o centro da polícia e do Ministério do Interior. O palácio é particularmente conhecido pelos tiros de canhão do Ramadã, uma tradição em que um tiro é disparado diariamente para sinalizar a quebra do jejum ao pôr do sol. Embora as funções governamentais tenham sido transferidas para edifícios modernos, o Palácio Naif continua a ser um marco histórico importante e continua a ser utilizado para fins cerimoniais para honrar a longa história do Estado de Direito no Kuwait.",
      fr: "Le palais Naif a été construit en 1919 sous le règne du cheikh Salem Al-Mubarak Al-Sabah. Initialement conçu comme un domaine agricole, il a rapidement été transformé en premier quartier général de la sécurité publique du pays. Construit en briques de boue, le palais est un excellent exemple de l'architecture traditionnelle du Najd, avec ses hauts murs, ses petites fenêtres et sa grande cour centrale. Pendant des décennies, il a été le centre de la police et du ministère de l'Intérieur. Le palais est particulièrement connu pour les tirs de canon du Ramadan, une tradition consistant à tirer un coup de canon quotidien pour signaler la rupture du jeûne au coucher du soleil. Bien que les fonctions gouvernementales aient depuis été transférées dans des bâtiments modernes, le palais Naif reste un monument historique important et continue d'être utilisé à des fins cérémonielles pour honorer la longue histoire de l'État de droit au Koweït.",
    },
