      fr: ["Année de construction : 1919", "Constructeur : Cheikh Salem Al-Mubarak Al-Sabah", "Objectif initial : Domaine agricole", "Fonction ultérieure : Quartier général de la sécurité publique", "Style architectural : Traditionnel du Najd", "Matériau : Briques de boue", "Tradition célèbre : Canon du Ramadan", "Statut actuel : Monument historique"],
