      fr: ["Époque de la présence portugaise : XVIe siècle", "Objectif des Portugais : Contrôle des routes des épices", "Bases régionales : Bahreïn, Ormuz", "Attribution contestée : Possiblement séleucide/islamique", "Emplacement : Côte de l'île de Failaka", "Importance stratégique : Contrôle du nord du Golfe", "État : Ruines, site archéologique", "Symbolique : Histoire coloniale de la région"],
