      pt: ["Construtor: Sheikh Khazal al-Kabi", "Ano de construção: 1916", "Título de Khazal: Emir de Mohammerah (Irão)", "Objetivo: Residência e quartel-general político no Kuwait", "Arquitetura: Mistura persa-kuwaitiana", "Declínio: Após a queda de Khazal em 1925", "Importância: Testemunho da política de poder regional", "Contexto histórico: Era pré-estados nacionais"],
