      en: ["Period: Sasanian (c. 224-651 AD)", "Religion: Nestorian Christianity", "Key discovery: 5th-6th century church", "Evidence for: Pre-Islamic Christian communities", "Artifacts: Stucco crosses", "Typical architecture: Church of the East", "Probable function: Trading post", "Significance: Refutes isolation, shows multiculturalism"],
      es: ["Período: Sasánida (aprox. 224-651 d. C.)", "Religión: Cristianismo nestoriano", "Hallazgo principal: Iglesia del siglo V/VI", "Evidencia de: Comunidades cristianas preislámicas", "Artefactos: Cruces de estuco", "Arquitectura típica: Iglesia de Oriente", "Función probable: Puesto comercial", "Importancia: Refuta el aislamiento, muestra el multiculturalismo"],
      pt: ["Período: Sassânida (aprox. 224-651 d.C.)", "Religião: Cristianismo nestoriano", "Principal descoberta: Igreja do século V/VI", "Evidência de: Comunidades cristãs pré-islâmicas", "Artefactos: Cruzes de estuque", "Arquitetura típica: Igreja do Oriente", "Função provável: Posto comercial", "Importância: Refuta o isolamento, mostra o multiculturalismo"],
      fr: ["Période : Sassanide (v. 224-651 ap. J.-C.)", "Religion : Christianisme nestorien", "Découverte majeure : Église du Ve/VIe siècle", "Preuve de : Communautés chrétiennes préislamiques", "Artéfacts : Croix en stuc", "Architecture typique : Église d'Orient", "Fonction probable : Poste de traite", "Importance : Réfute l'isolation, montre le multiculturalisme"],
