    image: "/poi-images/al-hashemi-ii-monument-history-v2.webp",
    description: {
      de: "Ein monumentales hölzernes Dhau-Schiff, das das reiche maritime Erbe Kuwaits ehrt.",
      hu: "Monumentális fából készült dhow hajó, amely Kuvait gazdag tengeri öröksége előtt tiszteleg.",
      ro: "O navă dhow monumentală din lemn care onorează bogatul patrimoniu maritim al Kuweitului.",
      en: "A monumental wooden dhow ship honoring Kuwait's rich maritime heritage.",
      es: "Un monumental barco dhow de madera que honra la rica herencia marítima de Kuwait.",
      pt: "Um monumental dhow de madeira que homenageia a rica herança marítima do Kuwait.",
      fr: "Un boutre monumental en bois qui honore le riche héritage maritime du Koweït.",
    },
    facts: {
      de: [
        "Das größte hölzerne Dhau-Schiff der Welt.",
        "Im Guinness-Buch der Rekorde verzeichnet."
      ],
      hu: [
        "A világ legnagyobb fából készült dhow hajója.",
        "Szerepel a Guinness Rekordok Könyvében."
      ],
      ro: [
        "Cea mai mare navă dhow de lemn din lume.",
        "Înscrisă în Cartea Recordurilor Guinness."
      ],
      en: [
        "The largest wooden dhow ship in the world.",
        "Listed in the Guinness Book of Records."
      ],
      es: ["El dhow de madera más grande del mundo.", "Registrado en el Libro Guinness de los Récords."],
      pt: ["O maior dhow de madeira do mundo.", "Registado no Livro Guinness dos Recordes."],
      fr: ["Le plus grand boutre en bois du monde.", "Inscrit au Livre Guinness des records."],
    }, image: "/poi-images/al-hashemi-ii-monument-history-v2.webp",
    descriptionAdvanced: {
      de: "Die Al-Hashemi II ist eine bemerkenswerte Leistung der modernen Holzschiffbaukunst und eine Hommage an Kuwaits reiches maritimes Erbe. Sie wurde von der Familie Al-Radwan, einer bekannten kuwaitischen Familie, in Auftrag gegeben und gebaut. Sie ist im Guinness-Buch der Rekorde als das größte hölzerne Dhau der Welt verzeichnet. Mit einer Länge von 80,4 Metern und einer Breite von 18,7 Metern ist sie eine Nachbildung einer traditionellen 'Baghlah'-Dhau, die früher für den Handel im Indischen Ozean verwendet wurde. Obwohl sie voll seetüchtig ist, hat sie nie den Hafen verlassen und dient stattdessen als prächtiger Veranstaltungsort und maritimes Museum neben dem Radisson Blu Hotel. Der Bau dauerte mehrere Jahre und erforderte das Fachwissen traditioneller Schiffbauer. Das Schiff ist ein Symbol des Nationalstolzes und erinnert an die Zeit, als Kuwaits Wohlstand vom Meer, dem Perlenhandel und dem Seehandel abhing.",
      hu: "Az Al-Hashemi II a modern fa hajóépítés figyelemre méltó teljesítménye és tisztelgés Kuvait gazdag tengeri öröksége előtt. Az Al-Radwan család, egy ismert kuvaiti család megbízásából épült. A Guinness Rekordok Könyvében a világ legnagyobb fa dhow-jaként tartják számon. 80,4 méter hosszú és 18,7 méter széles, egy hagyományos 'Baghlah' dhow másolata, amelyet egykor az Indiai-óceánon folytatott kereskedelemre használtak. Bár teljesen tengerképes, soha nem hagyta el a kikötőt, ehelyett pazar rendezvényhelyszínként és tengerészeti múzeumként szolgál a Radisson Blu Hotel mellett. Az építés több évig tartott, és hagyományos hajóépítők szakértelmét igényelte. A hajó a nemzeti büszkeség szimbóluma, és arra az időre emlékeztet, amikor Kuvait jóléte a tengertől, a gyöngyhalászattól és a tengeri kereskedelemtől függött.",
      ro: "Al-Hashemi II este o realizare remarcabilă a construcțiilor navale moderne din lemn și un omagiu adus bogatului patrimoniu maritim al Kuweitului. Comandată și construită de familia Al-Radwan, o proeminentă familie kuwaitiană, aceasta deține recordul mondial Guinness pentru cel mai mare dhow din lemn din lume. Măsurând 80,4 metri în lungime și 18,7 metri în lățime, este o replică a unui dhow tradițional de tip 'Baghlah', folosit odinioară pentru comerțul în Oceanul Indian. Deși este complet navigabilă, nu a părăsit niciodată portul, servind în schimb ca un loc de evenimente somptuos și muzeu maritim lângă Hotelul Radisson Blu. Construcția a durat câțiva ani și a necesitat expertiza constructorilor de nave tradiționali. Nava este un simbol al mândriei naționale, amintind de epoca în care prosperitatea Kuweitului depindea de mare, de scufundările după perle și de comerțul maritim.",
      en: "The Al-Hashemi II is a remarkable feat of modern wooden shipbuilding and a tribute to Kuwait's rich maritime heritage. Commissioned and built by the Al-Radwan family, a prominent Kuwaiti family, it holds the Guinness World Record for the largest wooden dhow in the world. Measuring 80.4 meters in length and 18.7 meters in width, it is a replica of a traditional 'Baghlah' type dhow, once used for trade across the Indian Ocean. Although fully seaworthy, it has never left port, serving instead as a lavish events venue and maritime museum adjacent to the Radisson Blu Hotel. The construction took several years and required the expertise of traditional shipwrights. The ship stands as a symbol of national pride, harking back to the era when Kuwait's prosperity depended on the sea, pearl diving, and maritime trade.",
      es: "El Al-Hashemi II es un logro notable del arte moderno de la construcción naval en madera y un homenaje a la rica herencia marítima de Kuwait. Fue encargado y construido por la familia Al-Radwan, una conocida familia kuwaití. Figura en el Libro Guinness de los Récords como el dhow de madera más grande del mundo. Con una longitud de 80,4 metros y una anchura de 18,7 metros, es una réplica de un dhow tradicional 'Baghlah', que antiguamente se utilizaba para el comercio en el Océano Índico. Aunque es plenamente apto para la navegación, nunca ha abandonado el puerto y sirve, en cambio, como un magnífico lugar para eventos y museo marítimo junto al hotel Radisson Blu. La construcción duró varios años y requirió la experiencia de constructores navales tradicionales. El barco es un símbolo de orgullo nacional y recuerda la época en que la prosperidad de Kuwait dependía del mar, el comercio de perlas y el comercio marítimo.",
      pt: "O Al-Hashemi II é uma proeza notável da construção naval moderna em madeira e uma homenagem à rica herança marítima do Kuwait. Foi encomendado e construído pela família Al-Radwan, uma conhecida família kuwaitiana. Está registado no Livro Guinness dos Recordes como o maior dhow de madeira do mundo. Com um comprimento de 80,4 metros e uma largura de 18,7 metros, é uma réplica de um tradicional dhow 'Baghlah', utilizado antigamente para o comércio no Oceano Índico. Embora seja totalmente navegável, nunca saiu do porto, servindo em vez disso como um magnífico local de eventos e museu marítimo junto ao hotel Radisson Blu. A construção demorou vários anos e exigiu a perícia de construtores navais tradicionais. O navio é um símbolo de orgulho nacional e recorda o tempo em que a prosperidade do Kuwait dependia do mar, da pesca de pérolas e do comércio marítimo.",
      fr: "L'Al-Hashemi II est une prouesse remarquable de la construction navale moderne en bois et un hommage au riche héritage maritime du Koweït. Il a été commandé et construit par la famille Al-Radwan, une célèbre famille koweïtienne. Il est inscrit au Livre Guinness des records comme le plus grand boutre (dhow) en bois au monde. Avec une longueur de 80,4 mètres et une largeur de 18,7 mètres, il s'agit d'une réplique d'un boutre traditionnel de type 'Baghlah', autrefois utilisé pour le commerce dans l'océan Indien. Bien qu'il soit tout à fait apte à la navigation, il n'a jamais quitté le port et sert de magnifique lieu de réception et de musée maritime à côté de l'hôtel Radisson Blu. La construction a duré plusieurs années et a nécessité le savoir-faire de constructeurs navals traditionnels. Le navire est un symbole de fierté nationale et rappelle l'époque où la prospérité du Koweït dépendait de la mer, de la pêche aux perles et du commerce maritime.",
    },
