      pt: ["Recorde: Maior dhow de madeira do mundo (Livro Guinness)", "Comprimento: 80,4 metros", "Largura: 18,7 metros", "Tipo: Réplica de um dhow 'Baghlah'", "Construtor: Família Al-Radwan", "Uso atual: Local de eventos, museu", "Localização: Ao lado do hotel Radisson Blu", "Simbolismo: Herança marítima do Kuwait"],
